package carrier

import (
	"math"
	"reflect"
	"sync"
	"testing"

	v "github.com/Naenier/ED-Copilot/internal/value"
)

func calculatorConfigure(t *testing.T, c *Calculator, input M) M {
	t.Helper()
	if err := c.Update(input); err != nil {
		t.Fatal(err)
	}
	return v.Obj(c.Snapshot()["summary"])
}
func calculatorAllServices(c *Calculator, state string) M {
	values := M{}
	for _, s := range v.Rows(c.Snapshot()["services"]) {
		if !v.Bool(s["mandatory"]) {
			values[v.Str(s["key"])] = state
		}
	}
	return values
}

// These are independently summed game-data scenarios, not values generated by
// a second implementation of the calculator under test.
func TestCarrierCalculatorKnownConfigurations(t *testing.T) {
	for _, tc := range []struct {
		kind, state                  string
		purchase, weekly, used, free float64
		count                        int
	}{
		{"fleet", "off", 5000000000, 5000000, 0, 25000, 11},
		{"fleet", "active", 6750000000, 34950000, 6620, 18380, 11},
		{"fleet", "suspended", 6750000000, 16800000, 6620, 18380, 11},
		{"squadron", "off", 25000000000, 10000000, 3000, 57000, 9},
		{"squadron", "active", 26185000000, 29600000, 6270, 53730, 9},
		{"squadron", "suspended", 26185000000, 17900000, 6270, 53730, 9},
	} {
		t.Run(tc.kind+"/"+tc.state, func(t *testing.T) {
			c := NewCalculator(nil)
			calculatorConfigure(t, c, M{"action": "select", "carrierType": tc.kind})
			s := calculatorConfigure(t, c, M{"services": calculatorAllServices(c, tc.state)})
			closeNumber(t, s["totalBuyPrice"], tc.purchase)
			closeNumber(t, s["weeklyUpkeep"], tc.weekly)
			closeNumber(t, s["servicesCapacityTons"], tc.used)
			closeNumber(t, s["availableCargoTons"], tc.free)
			if len(v.Rows(c.Snapshot()["services"])) != tc.count {
				t.Fatal("incorrect service availability")
			}
		})
	}
}

func TestCarrierCalculatorPerServiceAndSuspensionKeepsMassAndPurchase(t *testing.T) {
	c := NewCalculator(nil)
	before := v.Obj(c.Snapshot()["summary"])
	for _, service := range v.Rows(c.Snapshot()["services"]) {
		key := v.Str(service["key"])
		active := calculatorConfigure(t, c, M{"action": "service", "serviceKey": key, "state": "active"})
		closeNumber(t, active["totalBuyPrice"], v.Num(before["totalBuyPrice"])+v.Num(service["installationPrice"]))
		closeNumber(t, active["weeklyUpkeep"], v.Num(before["weeklyUpkeep"])+v.Num(service["activeWeeklyUpkeep"]))
		paused := calculatorConfigure(t, c, M{"action": "service", "serviceKey": key, "state": "suspended"})
		closeNumber(t, paused["totalBuyPrice"], v.Num(active["totalBuyPrice"]))
		closeNumber(t, paused["servicesCapacityTons"], v.Num(active["servicesCapacityTons"]))
		closeNumber(t, paused["weeklyUpkeep"], v.Num(before["weeklyUpkeep"])+v.Num(service["suspendedWeeklyUpkeep"]))
		removed := calculatorConfigure(t, c, M{"action": "service", "serviceKey": key, "state": "off"})
		closeNumber(t, removed["totalBuyPrice"], v.Num(before["totalBuyPrice"]))
		closeNumber(t, removed["servicesCapacityTons"], 0)
	}
}

func TestCarrierCalculatorExactPeriodsAndFuelAreSeparate(t *testing.T) {
	c := NewCalculator(nil)
	s := v.Obj(c.Snapshot()["summary"])
	closeNumber(t, s["monthlyUpkeep"], 21428571)
	// 5,000,000 * 365 / 7 rounded to a credit is 260,714,286. An
	// approximate floating multiplier used by PTN loses one credit here.
	closeNumber(t, s["yearlyUpkeep"], 260714286)
	closeNumber(t, s["weeklyFuelCost"], 0)
	s = calculatorConfigure(t, c, M{"jumpsPerWeek": 4})
	closeNumber(t, s["weeklyJumpCost"], 400000)
	closeNumber(t, s["weeklyUpkeep"], 5400000)
	if s["weeklyFuelCost"] != nil || s["weeklyCostWithFuel"] != nil || s["requiredBudget"] != nil {
		t.Fatal("missing fuel became free fuel", s)
	}
	s = calculatorConfigure(t, c, M{"tritiumPerJump": 80})
	closeNumber(t, s["weeklyTritiumTons"], 320)
	if s["weeklyFuelCost"] != nil {
		t.Fatal("missing fuel price became zero")
	}
	s = calculatorConfigure(t, c, M{"tritiumPrice": 50000, "reserveWeeks": 10, "bankBalance": 214000000, "purchaseBudget": 5214000000})
	closeNumber(t, s["weeklyFuelCost"], 16000000)
	closeNumber(t, s["weeklyCostWithFuel"], 21400000)
	closeNumber(t, s["minimumBankReserve"], 54000000)
	closeNumber(t, s["recommendedBankReserve"], 214000000)
	closeNumber(t, s["requiredBudget"], 5214000000)
	closeNumber(t, s["bankWholeWeeksWithFuel"], 10)
	closeNumber(t, s["budgetGap"], 0)
	if s["affordable"] != true {
		t.Fatal("exactly sufficient budget rejected", s)
	}
	s = calculatorConfigure(t, c, M{"carrierType": "squadron", "jumpsPerWeek": 4, "tritiumPerJump": 80, "tritiumPrice": 50000})
	closeNumber(t, s["weeklyJumpCost"], 800000)
	closeNumber(t, s["weeklyUpkeep"], 10800000)
	closeNumber(t, s["weeklyCostWithFuel"], 26800000)
}

func TestCarrierCalculatorKnownZeroUnknownAndCapacity(t *testing.T) {
	c := NewCalculator(nil)
	s := calculatorConfigure(t, c, M{"jumpsPerWeek": 1, "bankBalance": 0, "purchaseBudget": 0, "cargoTons": 30000})
	closeNumber(t, s["bankWholeWeeksWithoutFuel"], 0)
	closeNumber(t, s["availableCargoTons"], 0)
	closeNumber(t, s["overCapacityTons"], 5000)
	if s["capacityFits"] != false || s["affordable"] != false {
		t.Fatal(s)
	}
	s = calculatorConfigure(t, c, M{"purchaseBudget": 1e12, "bankBalance": nil})
	if s["affordable"] != nil || s["bankWeeksWithoutFuel"] != nil || s["requiredBudget"] != nil {
		t.Fatal("unknown values asserted as known", s)
	}
	s = calculatorConfigure(t, c, M{"reserveWeeks": 0})
	closeNumber(t, s["requiredBudget"], 5000000000)
	closeNumber(t, s["recommendedBankReserve"], 0)
	if s["affordable"] != true {
		t.Fatal("zero reserve does not require a fuel forecast", s)
	}
	s = calculatorConfigure(t, c, M{"reserveWeeks": 1, "tritiumPerJump": 0, "tritiumPrice": 0})
	closeNumber(t, s["weeklyFuelCost"], 0)
	if !v.Bool(s["fuelCostKnown"]) {
		t.Fatal("explicit zero lost")
	}
}

func TestCarrierCalculatorIndependentTypesRoundTripAndImmutableSnapshots(t *testing.T) {
	c := NewCalculator(nil)
	calculatorConfigure(t, c, M{"services": M{"shipyard": "active", "blackmarket": "suspended"}, "jumpsPerWeek": 7, "bankBalance": 123456789})
	calculatorConfigure(t, c, M{"action": "select", "carrierType": "squadron"})
	calculatorConfigure(t, c, M{"services": M{"refuel": "suspended"}, "jumpsPerWeek": 2, "purchaseBudget": 26000000000})
	copy := NewCalculator(c.ExportSettings())
	if !reflect.DeepEqual(c.Snapshot(), copy.Snapshot()) {
		t.Fatal("saved per-type plans changed on restart")
	}
	calculatorConfigure(t, copy, M{"action": "select", "carrierType": "fleet"})
	s := copy.Snapshot()
	if v.Int(v.At(s, "options", "jumpsPerWeek")) != 7 || v.At(s, "options", "services", "shipyard") != "active" || v.At(s, "options", "services", "blackmarket") != "suspended" {
		t.Fatal("switch lost fleet settings", s)
	}
	// Neither caller input nor returned maps are retained by the planner.
	input := M{"services": M{"refuel": "active"}}
	calculatorConfigure(t, copy, input)
	v.Obj(input["services"])["refuel"] = "off"
	snap := copy.Snapshot()
	v.Obj(v.Obj(snap["options"])["services"])["refuel"] = "off"
	if v.At(copy.Snapshot(), "options", "services", "refuel") != "active" {
		t.Fatal("snapshot/input shared mutable state")
	}
	calculatorConfigure(t, copy, M{"action": "reset"})
	if v.At(copy.Snapshot(), "options", "services", "shipyard") != "off" {
		t.Fatal("fleet plan did not reset")
	}
	calculatorConfigure(t, copy, M{"action": "select", "carrierType": "squadron"})
	if v.Int(v.At(copy.Snapshot(), "options", "jumpsPerWeek")) != 2 {
		t.Fatal("reset affected the other type")
	}
}

func TestCarrierCalculatorRejectsInvalidUpdatesAtomically(t *testing.T) {
	c := NewCalculator(nil)
	calculatorConfigure(t, c, M{"carrierType": "squadron"})
	for _, bad := range []M{
		{"carrierType": "other"}, {"action": "buy-in-game"}, {"services": M{"shipyard": "off"}}, {"services": M{"shipyard": "suspended"}}, {"services": M{"blackmarket": "active"}}, {"services": M{"voucherredemption": "active"}}, {"services": M{"repair": "unknown"}}, {"services": []string{"repair"}},
		{"action": "service", "state": "active"}, {"jumpsPerWeek": 1.5}, {"jumpsPerWeek": -1}, {"reserveWeeks": nil}, {"reserveWeeks": 521}, {"bankBalance": -1}, {"tritiumPrice": 1.1}, {"purchaseBudget": math.Inf(1)}, {"tritiumPerJump": math.NaN()}, {"cargoTons": true},
		{"jumpsPerWeek": 9, "services": M{"nonexistent": "active"}},
	} {
		before := c.ExportSettings()
		if err := c.Update(bad); err == nil {
			t.Fatalf("invalid input accepted: %#v", bad)
		}
		if !reflect.DeepEqual(before, c.ExportSettings()) {
			t.Fatalf("failed update changed state: %#v", bad)
		}
	}
	badSaved := NewCalculator(M{"selectedType": "other", "plans": M{"fleet": M{"services": M{"missing": "active"}}, "squadron": M{"bankBalance": -1}}})
	if badSaved.Snapshot()["selectedType"] != "fleet" {
		t.Fatal("invalid saved plan corrupted defaults")
	}
}

func TestCarrierCalculatorConcurrentSnapshotsAndUpdates(t *testing.T) {
	c := NewCalculator(nil)
	var wg sync.WaitGroup
	for worker := range 4 {
		wg.Add(1)
		go func(index int) {
			defer wg.Done()
			for step := range 25 {
				if index%2 == 0 {
					if err := c.Update(M{"jumpsPerWeek": step}); err != nil {
						t.Error(err)
					}
				} else {
					snapshot := c.Snapshot()
					if len(v.Rows(snapshot["services"])) != 11 {
						t.Error("partial snapshot")
					}
					_ = c.ExportSettings()
				}
			}
		}(worker)
	}
	wg.Wait()
}
